var urls = [];
var id = result.match(/\/article\/(\d+)\.html/);
if (id) {
    var num = parseInt(id[1]);
    for (var i = 1; i <= 1000; i++) {
        urls.push({"title": "第" + i + "章", "url": "https://m.bugexs.com/chapter/" + num + "_" + i + ".html"});
    }
}
JSON.stringify(urls);
